(() => {
  const style = document.createElement('style');
  style.textContent = `.journey{max-width:980px;margin:0 auto}.journey-hero{padding:30px;border-radius:24px;background:var(--navy);color:#fff;box-shadow:var(--shadow)}.journey-hero h2{margin:8px 0;font-size:clamp(1.6rem,3vw,2.35rem)}.journey-hero p{margin:0;color:#dbe8f5;line-height:1.65;max-width:720px}.journey-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:18px 0}.journey-step{padding:16px;border-radius:16px;background:#fff;border:1px solid var(--line)}.journey-step b{display:block;color:var(--navy);font-size:.95rem}.journey-step small{display:block;color:var(--muted);line-height:1.5;margin-top:6px}.journey-step.active{border-color:var(--blue);background:#f6faff}.journey-step.done{background:var(--mint);border-color:#a9d9c4}.journey-work{margin-top:18px;padding:28px;border-radius:24px;background:#fff;box-shadow:var(--shadow)}.journey-work h2{margin:8px 0;color:var(--navy)}.journey-work p{line-height:1.7}.unit-card{padding:16px;border-top:1px solid var(--line)}.unit-card:first-of-type{border-top:0}.unit-card b{color:var(--navy)}.unit-card input,.unit-card textarea{display:block;width:100%;margin-top:10px;padding:11px 12px;border:1px solid var(--line);border-radius:10px;font:inherit}.unit-card textarea{min-height:85px;resize:vertical}.hint{margin-top:9px;padding:10px 12px;background:#f6faff;border-radius:10px;color:#314963;line-height:1.6}.passage{padding:18px;border-radius:14px;background:#f6faff;border:1px solid #d7e5f4;line-height:1.8;font-family:Georgia,serif}.evidence{margin-top:12px;padding:12px;border:1px dashed #9bb0c7;border-radius:11px;background:#fff}.journey-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.journey-note{color:var(--muted);font-size:.86rem}.quiz-feedback{display:none;margin-top:10px;padding:12px;border-radius:10px;line-height:1.6}.quiz-feedback.show{display:block}.quiz-feedback.ok{background:var(--mint);color:#245846}.quiz-feedback.bad{background:#fff4f1;color:#8b3c35}@media(max-width:720px){.journey-grid{grid-template-columns:1fr}.journey-work{padding:21px}}`;
  document.head.appendChild(style);
  const todayKey = () => new Date().toISOString().slice(0,10);
  const storageKey = 'ci-jing-curriculum-v1';
  const getState = () => { try { return JSON.parse(localStorage.getItem(storageKey)) || { date: todayKey(), done: [] }; } catch { return { date: todayKey(), done: [] }; } };
  const setState = value => localStorage.setItem(storageKey, JSON.stringify(value));
  const words = [
    ['provide','提供；provide sb with sth','The library provides students with a quiet place to read.'],
    ['reflect','反映，体现','The survey reflects what students need most.'],
    ['acquire','逐步获得；acquire knowledge / skills','Students acquire useful skills through regular practice.'],
    ['affect','影响（动词）','A lack of sleep may affect concentration.'],
    ['measure','衡量，评估','We should measure progress by evidence.'],
    ['illustrate','说明，阐明','A clear example can illustrate a difficult idea.']
  ];
  const grammar = [
    ['If I ___ you, I would ask the teacher for help. (be)','were','先判断：这是与现在事实相反的假设；书面语常用 were。'],
    ['Not only did she finish the report, ___ she also explained the data.','but','not only 与 but also 对应；句首 not only 引起前半句部分倒装。'],
    ['The book ___ by the student won a prize. (write)','written','book 是“被写”，用过去分词作后置定语。'],
    ['___ the report, she sent it to her teacher. (finish)','Having finished','先完成再发送，且逻辑主语都是 she。']
  ];
  const reading = `<div class="passage"><b>编辑阅读材料 · 证据推断</b><br><br>A school library began opening for one extra hour after classes. In the first month, more students visited the library, especially those preparing group projects. Some students said the quieter space helped them concentrate. However, the school did not compare their exam results with those of students who did not use the library. The librarian therefore described the change as “a useful service improvement”, rather than proof that the extra hour raised academic achievement.</div><div class="unit-card"><b>1. 能直接确定的事实是什么？</b><textarea data-answer="more students visited the library" placeholder="写出文本明确说出的事实"></textarea></div><div class="unit-card"><b>2. 为什么不能推出“延长开放时间一定提高成绩”？</b><textarea data-answer="did not compare exam results" placeholder="写出限制结论的证据"></textarea></div><div class="unit-card"><b>3. 写出你的推理链：结论—证据—限制。</b><textarea placeholder="不要只写最终结论"></textarea></div>`;
  const cloze = `<div class="passage"><b>编辑完形篇章 · 逻辑与搭配</b><br><br>When Mia first joined the reading club, she tried to finish every book as quickly as possible. After several weeks, however, she found that speed did not always lead to understanding. Her teacher suggested that she ___ (1) short notes while reading and return to confusing parts later. Mia then began to notice how examples ___ (2) the writer’s main idea. She also learned to ___ (3) attention to linking words, because they often showed whether a paragraph was adding information, making a contrast, or giving a result. The habit took only ten minutes a day, but it made her reading more ___ (4) and less stressful.</div><div class="unit-card"><b>按顺序填空：1–4</b><input data-answer="take" placeholder="1"><input data-answer="illustrated" placeholder="2"><input data-answer="pay" placeholder="3"><input data-answer="effective" placeholder="4"><div class="hint">先读完整篇章：第 1 空考 take notes；第 2 空判断 examples 与 main idea 的关系；第 3 空考搭配；第 4 空根据前后意义判断。</div></div>`;
  const translation = `<div class="unit-card"><b>中译英</b><p>只有把证据放回原文，推断才有依据。</p><textarea data-answer="Only by putting the evidence back into the original text can an inference be supported." placeholder="先写英语主干，再补充条件关系"></textarea><div class="hint">自检：① Only by 是否表达条件；② 主句是否倒装；③ evidence 与 inference 是否都表达完整。</div></div><div class="unit-card"><b>写作任务识别</b><p>给学校图书馆写一封建议信：说明一个问题，提出一条建议，并给出理由。</p><textarea placeholder="写出对象、目的、必须完成的信息和三点提纲"></textarea></div>`;
  const test = `<div class="unit-card"><b>1. 填入最合适的词：A lack of sleep may ___ students’ concentration.</b><input data-answer="affect" placeholder="答案"></div><div class="unit-card"><b>2. 填入：The club ___ members ___ a guide.</b><input data-answer="provides with" placeholder="答案"></div><div class="unit-card"><b>3. 填入：If I ___ more time, I would read the whole report. (have)</b><input data-answer="had" placeholder="答案"></div><div class="unit-card"><b>4. 阅读材料中，哪项证据限制了“延长开放时间提高成绩”的结论？</b><textarea data-answer="did not compare" placeholder="写出证据或意思"></textarea><div class="journey-note">提交前不显示答案；答错项目会标为下一日优先复习。</div></div>`;
  const units = [
    { id:'vocab', title:'词汇与搭配', time:'12 分钟', note:'6 个词 + 搭配与变式', render: () => '<p>每日固定项目。先读语境，再写义项和搭配；不要只选答案。</p>' + words.map((word,i) => '<div class="unit-card"><b>'+ (i+1) +'. '+word[0]+' · '+word[1]+'</b><p>'+word[2]+'</p><input placeholder="不看上方提示，写出核心义项或搭配" data-answer="'+word[1].split('；')[0]+'"></div>').join('') },
    { id:'grammar', title:'语法语境', time:'10 分钟', note:'一个主题 + 4 个递进变式', render: () => '<p>每日固定项目。先判断结构关系，再填空；答案不是规则本身。</p>' + grammar.map((row,i) => '<div class="unit-card"><b>'+ (i+1) +'. '+row[0]+'</b><input data-answer="'+row[1]+'" placeholder="填入答案"><div class="hint">'+row[2]+'</div></div>').join('') },
    { id:'main', title:'主训练', time:'15–20 分钟', note:'完整篇章轮换', render: () => '<p>今天安排：'+((new Date().getDate()%2)?'完整阅读与证据推断':'完整完形篇章')+'。这是一套编辑练习，不是上海高考正式真题。</p>'+((new Date().getDate()%2)?reading:cloze) },
    { id:'express', title:'翻译与写作', time:'5–8 分钟', note:'输出、核对、修改', render: () => '<p>每日短练。先独立表达，再按自检点修改；配置 AI 后可对作答进行解释和批注。</p>'+translation },
    { id:'test', title:'今日闭卷小测', time:'5 分钟', note:'换问法验证', render: () => '<p>不看前面内容完成。提交后统一显示结果；选择题不作为主要学习方式。</p>'+test }
  ];
  const hub = document.getElementById('studyHub');
  hub.innerHTML = `<div class="journey"><div class="journey-hero"><div class="eyebrow">每日路径 · 标准版 40 分钟</div><h2>固定打基础，用完整材料验证能力。</h2><p>词汇、搭配和语法每天出现；完形、阅读、翻译和写作按节奏轮换。学习完成后再做闭卷小测，错误回到明天的优先复习。</p><div class="journey-actions"><button class="primary" id="beginJourney">开始今天的标准学习</button></div></div><div class="journey-grid">${units.map((unit,index)=>'<article class="journey-step" data-step="'+unit.id+'"><b>'+(index+1)+'. '+unit.title+'</b><small>'+unit.time+'<br>'+unit.note+'</small></article>').join('')}</div><p class="journey-note">当前示范内容均为编辑练习。正式上海试题只在来源核验后进入正式数据库。</p></div>`;
  const shell = document.getElementById('studyShell');
  const start = () => { hub.classList.add('hidden'); shell.classList.remove('hidden'); renderUnit(0); };
  function renderUnit(index) {
    const unit = units[index], progress = getState();
    shell.innerHTML = `<div class="journey"><button class="secondary study-back" id="returnJourney">返回每日路径</button><div class="journey-work"><span class="badge">第 ${index+1} 段 · ${unit.time}</span><h2>${unit.title}</h2>${unit.render()}<div class="journey-actions"><button class="primary" id="completeUnit">完成这一段</button>${index ? '<button class="secondary" id="previousUnit">上一段</button>' : ''}</div><div class="quiz-feedback" id="unitFeedback"></div></div></div>`;
    document.getElementById('returnJourney').onclick = () => { shell.classList.add('hidden'); hub.classList.remove('hidden'); };
    document.getElementById('previousUnit')?.addEventListener('click', () => renderUnit(index-1));
    document.getElementById('completeUnit').onclick = () => {
      const inputs = [...shell.querySelectorAll('[data-answer]')]; let checked = 0, correct = 0;
      inputs.forEach(input => { const answer = input.dataset.answer.toLowerCase().replace(/\s/g,''); const value = input.value.toLowerCase().replace(/\s/g,''); if (value) { checked++; if (value.includes(answer) || answer.includes(value)) correct++; } });
      if (unit.id === 'test' && checked) { const feedback=document.getElementById('unitFeedback'); feedback.className='quiz-feedback show '+(correct===checked?'ok':'bad'); feedback.textContent=correct+' / '+checked+' 项符合参考答案。未通过项已标记为明日优先复习；请回看对应学习段。'; }
      progress.date=todayKey(); if(!progress.done.includes(unit.id)) progress.done.push(unit.id); setState(progress);
      if(index < units.length-1) { document.getElementById('completeUnit').textContent='进入下一段'; document.getElementById('completeUnit').onclick=()=>renderUnit(index+1); } else { document.getElementById('completeUnit').textContent='完成今日路径'; document.getElementById('completeUnit').onclick=()=>{shell.innerHTML='<div class="journey-work"><span class="badge">今日完成</span><h2>今天的学习闭环已完成。</h2><p>你完成了词汇搭配、语法、篇章训练、表达和闭卷小测。明天系统将优先安排未通过的小测内容与到期复习。</p><button class="primary" id="backToPath">查看每日路径</button></div>';document.getElementById('backToPath').onclick=()=>{shell.classList.add('hidden');hub.classList.remove('hidden');};}; }
    };
  }
  document.getElementById('beginJourney').addEventListener('click', start);
})();
